40	        int64_t numCores = AscendC::GetBlockNum();
41	        int64_t rowsPerCore = (totalRows_ + numCores - 1) / numCores;
42	        int64_t rowStart = coreIdx * rowsPerCore;
43	        int64_t rowEnd = (rowStart + rowsPerCore < totalRows_) ? (rowStart + rowsPerCore) : totalRows_;
44	
45	        for (int32_t row = rowStart; row < rowEnd; row += tileLength_) {
46	            int64_t curTileLength = (row + tileLength_ < rowEnd) ? tileLength_ : (rowEnd - row);
47	            CopyIn(row, curTileLength);
48	            Compute(curTileLength);
49	            CopyOut(row, curTileLength);
50	        }
51	    }
52	
53	private:
54	    __aicore__ inline void CopyIn(int64_t rowBase, int64_t curTileLength) {
55	        AscendC::LocalTensor<T> inputLocal = inQueue.AllocTensor<T>();
56	        AscendC::LocalTensor<T> r1Local = r1Queue.AllocTensor<T>();
57	        AscendC::LocalTensor<T> r2Local = r2Queue.AllocTensor<T>();
58	
59	        for (int32_t i = 0; i < curTileLength; i++) {
60	            int64_t globalRow = rowBase + i;
61	            int64_t bIdx = globalRow / (h_ * s_);
62	            int64_t rem = globalRow % (h_ * s_);
63	            int64_t hIdx = rem / s_;
64	            int64_t sIdx = rem % s_;
65	
66	            int64_t inputOffset = ((bIdx * h_ + hIdx) * s_ + sIdx) * d_;
67	            int64_t rOffset = ((bIdx * 1 + 0) * s_ + sIdx) * d_;
68	
69	            AscendC::DataCopy(inputLocal[i * d_], inputGm[inputOffset], d_);
70	            AscendC::DataCopy(r1Local[i * d_], r1Gm[rOffset], d_);
71	            AscendC::DataCopy(r2Local[i * d_], r2Gm[rOffset], d_);
72	        }
73	
74	        inQueue.EnQue(inputLocal);
75	        r1Queue.EnQue(r1Local);
76	        r2Queue.EnQue(r2Local);
77	    }
78	
79	    __aicore__ inline void Compute(int64_t curTileLength) {
80	        AscendC::LocalTensor<T> inputLocal = inQueue.DeQue<T>();
81	        AscendC::LocalTensor<T> r1Local = r1Queue.DeQue<T>();
82	        AscendC::LocalTensor<T> r2Local = r2Queue.DeQue<T>();
83	        AscendC::LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();
84	        AscendC::LocalTensor<T> rotatedLocal = rotatedBuf.Get<T>();
85	
86	        int64_t halfD = d_ / 2;
87	
88	        for (int32_t i = 0; i < curTileLength; i++) {
89	            int64_t rowOffset = i * d_;
90	
91	            if (rotaryMode_ == 0) {  // half mode
92	                // rotated = concat(-x2, x1)
93	                for (int32_t j = 0; j < halfD; j++) {
94	                    T neg_val = inputLocal.GetValue(rowOffset + halfD + j);
95	                    T pos_val = inputLocal.GetValue(rowOffset + j);
96	                    volatile float neg_f = (float)(neg_val);
97	                    volatile float pos_f = (float)(pos_val);
98	                    float neg_result = 0.0f - neg_f;
99	                    rotatedLocal.SetValue(rowOffset + j, (T)(neg_result));
100	                    rotatedLocal.SetValue(rowOffset + halfD + j, (T)(pos_f));
101	                }
102	            } else {  // interleave mode
103	                // rotated: even indices get -odd, odd indices get even
104	                for (int32_t j = 0; j < halfD; j++) {
105	                    T neg_val = inputLocal.GetValue(rowOffset + j * 2 + 1);
106	                    T pos_val = inputLocal.GetValue(rowOffset + j * 2);
107	                    volatile float neg_f = (float)(neg_val);
108	                    volatile float pos_f = (float)(pos_val);
109	                    float neg_result = 0.0f - neg_f;
110	                    rotatedLocal.SetValue(rowOffset + j * 2, (T)(neg_result));
111	                    rotatedLocal.SetValue(rowOffset + j * 2 + 1, (T)(pos_f));
112	                }
113	            }
114	
115	            // out = input * r1 + rotated * r2 (element-wise to avoid buffer conflicts)
116	            for (int32_t j = 0; j < d_; j++) {
117	                float in_val = (float)(inputLocal.GetValue(rowOffset + j));
118	                float r1_val = (float)(r1Local.GetValue(rowOffset + j));
119	                float rot_val = (float)(rotatedLocal.GetValue(rowOffset + j));
120	                float r2_val = (float)(r2Local.GetValue(rowOffset + j));
121	                float out_val = in_val * r1_val + rot_val * r2_val;
122	                outputLocal.SetValue(rowOffset + j, (T)(out_val));
123	            }
124	        }
125	
126	        outQueue.EnQue(outputLocal);
127	        inQueue.FreeTensor(inputLocal);
128	        r1Queue.FreeTensor(r1Local);
129	        r2Queue.FreeTensor(r2Local);
130	    }
131	
132	    __aicore__ inline void CopyOut(int64_t rowBase, int64_t curTileLength) {
133	        AscendC::LocalTensor<T> outputLocal = outQueue.DeQue<T>();
134	
135	        for (int32_t i = 0; i < curTileLength; i++) {
136	            int64_t globalRow = rowBase + i;
137	            int64_t bIdx = globalRow / (h_ * s_);
138	            int64_t rem = globalRow % (h_ * s_);
139	            int64_t hIdx = rem / s_;
140	            int64_t sIdx = rem % s_;
141	
142	            int64_t outputOffset = ((bIdx * h_ + hIdx) * s_ + sIdx) * d_;
143	            AscendC::DataCopy(outputGm[outputOffset], outputLocal[i * d_], d_);
144	        }
145	
146	        outQueue.FreeTensor(outputLocal);
147	    }
148	
149	private:
150	    AscendC::TPipe pipe;
151	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue;
152	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> r1Queue;
153	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> r2Queue;
154	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
155	    AscendC::TBuf<AscendC::TPosition::VECCALC> rotatedBuf;
156	
157	    AscendC::GlobalTensor<T> inputGm;
158	    AscendC::GlobalTensor<T> r1Gm;
159	    AscendC::GlobalTensor<T> r2Gm;
160	    AscendC::GlobalTensor<T> outputGm;
161	
162	    int64_t b_, h_, s_, d_;
163	    int64_t totalRows_;
164	    int64_t tileLength_;
165	    int64_t rotaryMode_;
166	};
