7	at::Tensor rotary_mul_kernel(const at::Tensor &input, const at::Tensor &r1, const at::Tensor &r2,
8	                             const std::string &rotary_mode) {
9	    // Input validation
10	    TORCH_CHECK(input.dim() == 4, "input must be 4D");
11	    TORCH_CHECK(r1.dim() == 4, "r1 must be 4D");
12	    TORCH_CHECK(r2.dim() == 4, "r2 must be 4D");
13	    TORCH_CHECK(input.dtype() == r1.dtype() && input.dtype() == r2.dtype(),
14	                "All tensors must have the same dtype");
15	
16	    int64_t b = input.size(0);
17	    int64_t h = input.size(1);
18	    int64_t s = input.size(2);
19	    int64_t d = input.size(3);
20	
21	    // Create output tensor
22	    auto output = at::empty_like(input);
23	
24	    // Get platform info
25	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
26	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
27	    uint64_t ubSize;
28	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
29	
30	    int64_t totalRows = b * h * s;
31	    int64_t usedCoreNum = std::min(coreNum, totalRows);
32	
33	    // Tiling: each core handles rowsPerCore rows
34	    int64_t rowsPerCore = (totalRows + usedCoreNum - 1) / usedCoreNum;
35	
36	    // UB tiling: tileLength rows per tile
37	    // Buffer layout: inQueue(BUFFER_NUM=2) + r1Queue(BUFFER_NUM=2) +
38	    //                r2Queue(BUFFER_NUM=2) + outQueue(BUFFER_NUM=2) + rotatedBuf(1)
39	    // Total coefficient = 4*2 + 1 = 9
40	    // For FP32: 9 * tileLength * d * 4 bytes
41	    // For FP16: 9 * tileLength * d * 2 bytes
42	    int64_t dtypeSize = (input.dtype() == at::kFloat) ? 4 : 2;
43	    int64_t dtypeFlag = (input.dtype() == at::kFloat) ? 0 : 1;
44	    int64_t bufferCoefficient = 9 * dtypeSize;
45	    int64_t tileLength = static_cast<int64_t>(ubSize) / (bufferCoefficient * d);
46	    tileLength = std::max(tileLength, static_cast<int64_t>(1));
47	    tileLength = std::min(tileLength, rowsPerCore);
48	
49	    // 32B alignment for tileLength * d * dtypeSize
50	    int64_t bytesPerRow = d * dtypeSize;
51	    int64_t alignBytes = 32;
52	    int64_t tileBytes = tileLength * bytesPerRow;
53	    tileBytes = (tileBytes + alignBytes - 1) / alignBytes * alignBytes;
54	    tileLength = tileBytes / bytesPerRow;
55	    if (tileLength == 0) tileLength = 1;
56	
57	    int64_t rotaryMode = (rotary_mode == "half") ? 0 : 1;
58	
59	    struct TilingData {
60	        int64_t b;
61	        int64_t h;
62	        int64_t s;
63	        int64_t d;
64	        int64_t totalRows;
65	        int64_t tileLength;
66	        int64_t rotaryMode;
67	        int64_t dtypeFlag;
68	    };
69	
70	    TilingData tilingData = {b, h, s, d, totalRows, tileLength, rotaryMode, dtypeFlag};
71	
72	    // Allocate workspace for tiling on CPU first, then copy to NPU
73	    auto tilingTensorCpu = at::empty({sizeof(TilingData)}, at::TensorOptions().dtype(at::kByte));
74	    auto tilingPtr = tilingTensorCpu.data_ptr<uint8_t>();
75	    memcpy(tilingPtr, &tilingData, sizeof(TilingData));
76	    auto tilingTensor = tilingTensorCpu.to(input.device());
77	
78	    int64_t blockDim = usedCoreNum;
79	
80	    EXEC_KERNEL_CMD(rotary_mul, blockDim, input, r1, r2, output, tilingTensor);
81	
82	    return output;
83	}
84	
85	at::Tensor rotary_mul(const at::Tensor &input, const at::Tensor &r1, const at::Tensor &r2,
86	                      const std::string &rotary_mode) {
87	    // AICore does not support scalar bfloat16 operations (fneg, type cast).
88	    // Fallback: compute in float32, then cast back.
89	    if (input.dtype() == at::kBFloat16) {
90	        auto input_f32 = input.to(at::kFloat);
91	        auto r1_f32 = r1.to(at::kFloat);
92	        auto r2_f32 = r2.to(at::kFloat);
93	        auto output_f32 = rotary_mul_kernel(input_f32, r1_f32, r2_f32, rotary_mode);
94	        return output_f32.to(at::kBFloat16);
95	    }
96	    return rotary_mul_kernel(input, r1, r2, rotary_mode);
97	}
