constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelInterleaveRope {
public:
    __aicore__ inline KernelInterleaveRope() {}

    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR output,
        int64_t b, int64_t n, int64_t s, int64_t d,
        int64_t totalRows, int64_t tileLength,
        int64_t cosHasBroadcast) {
        b_ = b;
        n_ = n;
        s_ = s;
        d_ = d;
        totalRows_ = totalRows;
        tileLength_ = tileLength;
        cosHasBroadcast_ = cosHasBroadcast;

        int64_t xSize = b_ * n_ * s_ * d_;
        int64_t cosSinSize = b_ * n_ * (cosHasBroadcast_ ? int64_t(1) : s_) * d_;
        int64_t ySize = b_ * n_ * s_ * d_;

        xGm.SetGlobalBuffer((__gm__ T *)x, xSize);
        cosGm.SetGlobalBuffer((__gm__ T *)cos, cosSinSize);
        sinGm.SetGlobalBuffer((__gm__ T *)sin, cosSinSize);
        yGm.SetGlobalBuffer((__gm__ T *)output, ySize);

        pipe.InitBuffer(xQueue, BUFFER_NUM, tileLength_ * d_ * sizeof(T));
        pipe.InitBuffer(cosQueue, BUFFER_NUM, tileLength_ * d_ * sizeof(T));
        pipe.InitBuffer(sinQueue, BUFFER_NUM, tileLength_ * d_ * sizeof(T));
        pipe.InitBuffer(yQueue, BUFFER_NUM, tileLength_ * d_ * sizeof(T));
    }

    __aicore__ inline void Process() {
        int64_t coreIdx = AscendC::GetBlockIdx();
        int64_t numCores = AscendC::GetBlockNum();
        int64_t rowsPerCore = (totalRows_ + numCores - 1) / numCores;
        int64_t rowStart = coreIdx * rowsPerCore;
        int64_t rowEnd = (rowStart + rowsPerCore < totalRows_) ? (rowStart + rowsPerCore) : totalRows_;

        for (int64_t row = rowStart; row < rowEnd; row += tileLength_) {
            int64_t curTileLength = (row + tileLength_ < rowEnd) ? tileLength_ : (rowEnd - row);
            CopyIn(row, curTileLength);
            Compute(curTileLength);
            CopyOut(row, curTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t rowBase, int64_t curTileLength) {
        AscendC::LocalTensor<T> xLocal = xQueue.AllocTensor<T>();
        AscendC::LocalTensor<T> cosLocal = cosQueue.AllocTensor<T>();
        AscendC::LocalTensor<T> sinLocal = sinQueue.AllocTensor<T>();

        for (int64_t i = 0; i < curTileLength; i++) {
            int64_t globalRow = rowBase + i;
            int64_t bIdx = globalRow / (n_ * s_);
            int64_t rem = globalRow % (n_ * s_);
            int64_t nIdx = rem / s_;
            int64_t sIdx = rem % s_;

            int64_t xOffset = ((bIdx * n_ + nIdx) * s_ + sIdx) * d_;
            int64_t cosSOffset = cosHasBroadcast_ ? int64_t(0) : sIdx;
            int64_t cosStride = cosHasBroadcast_ ? int64_t(1) : s_;
            int64_t cosOffset = ((bIdx * n_ + nIdx) * cosStride + cosSOffset) * d_;

            AscendC::DataCopy(xLocal[i * d_], xGm[xOffset], d_);
            AscendC::DataCopy(cosLocal[i * d_], cosGm[cosOffset], d_);
            AscendC::DataCopy(sinLocal[i * d_], sinGm[cosOffset], d_);
        }

        xQueue.EnQue(xLocal);
        cosQueue.EnQue(cosLocal);
        sinQueue.EnQue(sinLocal);
    }

    __aicore__ inline void Compute(int64_t curTileLength) {
        AscendC::LocalTensor<T> xLocal = xQueue.DeQue<T>();
        AscendC::LocalTensor<T> cosLocal = cosQueue.DeQue<T>();
        AscendC::LocalTensor<T> sinLocal = sinQueue.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = yQueue.AllocTensor<T>();

        int64_t halfD = d_ / 2;

        for (int64_t i = 0; i < curTileLength; i++) {
            int64_t rowOffset = i * d_;

            // Process each pair j: even=2*j, odd=2*j+1
            // output[j]       = x_even * cos[j]      - x_odd * sin[j]
            // output[j+halfD] = x_odd  * cos[j+halfD] + x_even * sin[j+halfD]
            for (int64_t j = 0; j < halfD; j++) {
                float xEven = (float)(xLocal.GetValue(rowOffset + j * 2));
                float xOdd  = (float)(xLocal.GetValue(rowOffset + j * 2 + 1));
                float cH1   = (float)(cosLocal.GetValue(rowOffset + j));
                float sH1   = (float)(sinLocal.GetValue(rowOffset + j));
                float cH2   = (float)(cosLocal.GetValue(rowOffset + halfD + j));
                float sH2   = (float)(sinLocal.GetValue(rowOffset + halfD + j));

                float yH1 = xEven * cH1 - xOdd * sH1;
                float yH2 = xOdd  * cH2 + xEven * sH2;

                yLocal.SetValue(rowOffset + j, (T)(yH1));
                yLocal.SetValue(rowOffset + halfD + j, (T)(yH2));
            }
        }

        yQueue.EnQue(yLocal);
        xQueue.FreeTensor(xLocal);
        cosQueue.FreeTensor(cosLocal);
        sinQueue.FreeTensor(sinLocal);
    }

    __aicore__ inline void CopyOut(int64_t rowBase, int64_t curTileLength) {
        AscendC::LocalTensor<T> yLocal = yQueue.DeQue<T>();

        for (int64_t i = 0; i < curTileLength; i++) {
            int64_t globalRow = rowBase + i;
            int64_t bIdx = globalRow / (n_ * s_);
            int64_t rem = globalRow % (n_ * s_);
            int64_t nIdx = rem / s_;
            int64_t sIdx = rem % s_;

            int64_t yOffset = ((bIdx * n_ + nIdx) * s_ + sIdx) * d_;
            AscendC::DataCopy(yGm[yOffset], yLocal[i * d_], d_);
        }

        yQueue.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> cosQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> sinQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yQueue;

    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> cosGm;
    AscendC::GlobalTensor<T> sinGm;
    AscendC::GlobalTensor<T> yGm;

    int64_t b_;
    int64_t n_;
    int64_t s_;
    int64_t d_;
    int64_t totalRows_;
    int64_t tileLength_;
    int64_t cosHasBroadcast_;
};

extern "C" __global__ __aicore__ void interleave_rope(
    GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR output, GM_ADDR tiling) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIV_ONLY);
    AscendC::TPipe pipe;

    // Read tiling data as int64_t array from GM
    int64_t b       = ((__gm__ int64_t *)tiling)[0];
    int64_t n       = ((__gm__ int64_t *)tiling)[1];
    int64_t s       = ((__gm__ int64_t *)tiling)[2];
    int64_t d       = ((__gm__ int64_t *)tiling)[3];
    int64_t totalRows   = ((__gm__ int64_t *)tiling)[4];
