namespace ascend_kernel {

at::Tensor interleave_rope_kernel(
    const at::Tensor &x,
    const at::Tensor &cos,
    const at::Tensor &sin) {
    // Input validation
    TORCH_CHECK(x.dim() == 4, "x must be 4D (B,N,S,D)");
    TORCH_CHECK(cos.dim() == 4, "cos must be 4D (B,N,S,D)");
    TORCH_CHECK(sin.dim() == 4, "sin must be 4D (B,N,S,D)");
    TORCH_CHECK(x.dtype() == cos.dtype() && x.dtype() == sin.dtype(),
                "All tensors must have the same dtype");
    TORCH_CHECK(x.size(3) == 64, "D dimension must be 64");
    TORCH_CHECK(x.is_contiguous() && cos.is_contiguous() && sin.is_contiguous(),
                "All inputs must be contiguous");

    int64_t b = x.size(0);
    int64_t n = x.size(1);
    int64_t s = x.size(2);
    int64_t d = x.size(3);
    int64_t cosS = cos.size(2);
    int64_t sinS = sin.size(2);

    TORCH_CHECK(cosS == 1 || cosS == s, "cos S must be 1 or ", s, ", got ", cosS);
    TORCH_CHECK(sinS == 1 || sinS == s, "sin S must be 1 or ", s, ", got ", sinS);
    int64_t cosHasBroadcast = (cosS == 1) ? 1 : 0;

    // Create output tensor
    auto output = at::empty_like(x);

    // Get platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t totalRows = b * n * s;
    int64_t usedCoreNum = std::min(coreNum, totalRows);

    // Tiling: each core handles rowsPerCore rows
    int64_t rowsPerCore = (totalRows + usedCoreNum - 1) / usedCoreNum;

    // UB tiling: tileLength rows per tile
    // Buffer layout: xQueue(2) + cosQueue(2) + sinQueue(2) + yQueue(2)
    // Total coefficient = 4 * 2 = 8
    int64_t dtypeSize = (x.dtype() == at::kFloat) ? 4 : 2;
    int64_t dtypeFlag = (x.dtype() == at::kFloat) ? 0 : 1;
    int64_t bufferCoefficient = 8 * dtypeSize;
    int64_t tileLength = static_cast<int64_t>(ubSize) / (bufferCoefficient * d);
    tileLength = std::max(tileLength, static_cast<int64_t>(1));
    tileLength = std::min(tileLength, rowsPerCore);

    // 32B alignment for tileLength * d * dtypeSize
    int64_t bytesPerRow = d * dtypeSize;
    int64_t alignBytes = 32;
    int64_t tileBytes = tileLength * bytesPerRow;
    tileBytes = (tileBytes + alignBytes - 1) / alignBytes * alignBytes;
    tileLength = tileBytes / bytesPerRow;
    if (tileLength == 0) tileLength = 1;

    struct TilingData {
        int64_t b;
        int64_t n;
        int64_t s;
        int64_t d;
        int64_t totalRows;
        int64_t tileLength;
        int64_t cosHasBroadcast;
        int64_t dtypeFlag;
    };

    TilingData tilingData = {b, n, s, d, totalRows, tileLength, cosHasBroadcast, dtypeFlag};

    // Allocate workspace for tiling on CPU, then copy to NPU
    auto tilingTensorCpu = at::empty({sizeof(TilingData)}, at::TensorOptions().dtype(at::kByte));
    auto tilingPtr = tilingTensorCpu.data_ptr<uint8_t>();
    memcpy(tilingPtr, &tilingData, sizeof(TilingData));
    auto tilingTensor = tilingTensorCpu.to(x.device());

    int64_t blockDim = usedCoreNum;

    EXEC_KERNEL_CMD(interleave_rope, blockDim, x, cos, sin, output, tilingTensor);

    return output;
}

at::Tensor interleave_rope(
    const at::Tensor &x,
    const at::Tensor &cos,
    const at::Tensor &sin) {
    // BF16: AICore scalar bfloat16 operations (fneg, type cast) are unreliable.
    // Fallback: convert to float32, compute, cast back.
    if (x.dtype() == at::kBFloat16) {
        auto xF32 = x.to(at::kFloat);
        auto cosF32 = cos.to(at::kFloat);
        auto sinF32 = sin.to(at::kFloat);
        auto outF32 = interleave_rope_kernel(xF32, cosF32, sinF32);
        return outF32.to(at::kBFloat16);
    }
    return interleave_rope_kernel(x, cos, sin);
}

